from flask import Flask, request
import sqlite3, os

app = Flask(__name__)
SECRET_KEY = 'abc123'

@app.route('/search')
def search():
    name = request.args.get('name')
    conn = sqlite3.connect('users.db')
    result = conn.execute(f"SELECT * FROM users WHERE name='{name}'").fetchall()
    return str(result)

@app.route('/run')
def run_cmd():
    cmd = request.args.get('cmd')
    return os.popen(cmd).read()
